<?php
require_once __DIR__.'/includes/bootstrap.php';require_role(['admin']);
$msg='';$roleNames=roles();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'create';
 if($action==='add_profile'){
  $name=trim($_POST['profile_name']??'');$college=trim($_POST['college']??'');$dept=trim($_POST['profile_department']??'');$code=trim($_POST['employee_code']??'');
  if(!$name||!$dept)$msg='Instructor name and department are required.';
  else{$q=$pdo->prepare('SELECT id FROM departments WHERE name=? AND is_active=1');$q->execute([$dept]);if(!$q->fetch())$msg='Choose an active department.';else{try{$s=$pdo->prepare('INSERT INTO instructors(full_name,college,department,employee_code) VALUES(?,?,?,?)');$s->execute([$name,$college,$dept,$code]);flash('success','Instructor profile added. It is now available when assigning evaluations.');redirect('users.php#instructor-profiles');}catch(PDOException $e){$msg='Could not add the instructor profile.';}}}
 }elseif($action==='toggle_profile'){
  $id=(int)($_POST['profile_id']??0);$s=$pdo->prepare('UPDATE instructors SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->execute([$id]);flash('success','Instructor profile status updated. Historical evaluation records are preserved.');redirect('users.php#instructor-profiles');
 }elseif($action==='delete'){
  $id=(int)($_POST['user_id']??0);if($id===(int)current_user()['id'])$msg='You cannot delete your own account while signed in.';else{$s=$pdo->prepare('SELECT id,role FROM users WHERE id=?');$s->execute([$id]);$target=$s->fetch();if(!$target)$msg='Account not found.';elseif($target['role']==='admin'&&(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='admin' AND is_active=1")->fetchColumn()<=1)$msg='The last active administrator cannot be deleted.';else{try{$s=$pdo->prepare('DELETE FROM users WHERE id=?');$s->execute([$id]);flash('success','User account deleted.');redirect('users.php');}catch(PDOException $e){$s=$pdo->prepare('UPDATE users SET is_active=0 WHERE id=?');$s->execute([$id]);flash('success','Account deactivated because existing records depend on it. Historical records were preserved.');redirect('users.php');}}}
 }elseif($action==='toggle_user'){$id=(int)($_POST['user_id']??0);if($id===(int)current_user()['id'])$msg='You cannot deactivate your own account.';else{$s=$pdo->prepare('UPDATE users SET is_active=IF(is_active=1,0,1) WHERE id=?');$s->execute([$id]);flash('success','User account status updated.');redirect('users.php');}}
 else{
  $name=trim($_POST['full_name']??'');$username=trim($_POST['username']??'');$pass=(string)($_POST['password']??'');$role=$_POST['role']??'student';$dept=trim($_POST['department']??'');$iid=(int)($_POST['instructor_id']??0);
  if(!$name||!$username||$pass===''||!isset($roleNames[$role]))$msg='Complete all required fields.';
  elseif(strlen($pass)<12)$msg='Password must contain at least 12 characters.';
  elseif($role==='self'&&!$iid)$msg='Select the instructor profile linked to this instructor account.';
  else{try{$hash=password_hash($pass,PASSWORD_DEFAULT);$s=$pdo->prepare('INSERT INTO users(username,password_hash,full_name,role,department,instructor_id) VALUES(?,?,?,?,?,?)');$s->execute([$username,$hash,$name,$role,$dept,$iid?:null]);flash('success','User account created successfully. Share the username and password securely.');redirect('users.php');}catch(PDOException $e){$msg='Could not create account. The username may already exist, or the database may need the update migration.';}}
 }
}
$instructors=$pdo->query('SELECT id,full_name,department FROM instructors WHERE is_active=1 ORDER BY full_name')->fetchAll();
$departments=$pdo->query('SELECT name FROM departments WHERE is_active=1 ORDER BY name')->fetchAll();
$rows=$pdo->query('SELECT u.id,u.username,u.full_name,u.role,u.department,u.is_active,u.created_at,u.profile_image,i.full_name AS instructor_name FROM users u LEFT JOIN instructors i ON i.id=u.instructor_id ORDER BY u.created_at DESC')->fetchAll();
$profiles=$pdo->query('SELECT * FROM instructors ORDER BY is_active DESC,full_name')->fetchAll();
page_header('User Accounts');show_flash();
?>
<div class="page-intro"><div><div class="eyebrow">ADMINISTRATION</div><h1>User Accounts</h1><p>Create and manage accounts, assign roles, and maintain instructor names used in evaluation assignments from one place.</p></div><div class="actions"><a class="btn secondary" href="<?=BASE_URL?>/course_management.php">▦ Courses &amp; evaluation periods</a></div></div>
<?php if($msg):?><div class="alert error"><?=e($msg)?></div><?php endif;?>
<section class="panel"><h2>＋ Create user account</h2><p class="muted">Enter one account per person. Choose the role and department that match the user's responsibilities.</p><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Full name<input name="full_name" required autocomplete="name"></label><label>Username<input name="username" required autocomplete="off"></label><label>Password<div class="password-wrap"><input id="new-password" type="password" name="password" minlength="12" required autocomplete="new-password"><button class="btn small secondary" type="button" onclick="togglePassword('new-password',this)">Show</button></div></label><label>User role<select name="role" required><?php foreach($roleNames as $k=>$v):?><option value="<?=e($k)?>"><?=e($v)?></option><?php endforeach;?></select></label><label>Department<select name="department"><option value="">Not assigned</option><?php foreach($departments as $d):?><option value="<?=e($d['name'])?>"><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Linked instructor profile (required for instructor/self-evaluator)<select name="instructor_id"><option value="0">No linked instructor profile</option><?php foreach($instructors as $i):?><option value="<?=$i['id']?>"><?=e($i['full_name'].' — '.$i['department'])?></option><?php endforeach;?></select></label><div class="wide"><button class="btn primary">Create account</button></div></form></section>
<section class="panel table-wrap"><div class="section-head"><div><h2>Manage accounts</h2><p class="muted">Delete an account when safe; if evaluation or workflow history depends on it, the account is deactivated instead to preserve records.</p></div><span class="count-pill"><?=count($rows)?> accounts</span></div><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Linked instructor</th><th>Department</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if(!empty($r['profile_image'])):?><img class="table-avatar" src="<?=BASE_URL.'/'.e($r['profile_image'])?>" alt="Profile photo"><?php endif;?><?=e($r['full_name'])?></td><td><?=e($r['username'])?></td><td><?=e($roleNames[$r['role']]??$r['role'])?></td><td><?=e($r['instructor_name']??'—')?></td><td><?=e($r['department']??'—')?></td><td><?=$r['is_active']?'Active':'Inactive'?></td><td><div class="actions"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_user"><input type="hidden" name="user_id" value="<?=$r['id']?>"><button class="btn small secondary" <?=((int)$r['id']===(int)current_user()['id'])?'disabled':''?>><?=$r['is_active']?'Deactivate':'Activate'?></button></form><?php if((int)$r['id']!==(int)current_user()['id']):?><form method="post" onsubmit="return confirm('Delete this account? If records depend on it, it will be deactivated to preserve history.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=$r['id']?>"><button class="btn small danger">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></section>
<details class="panel integrated-instructors"><summary><strong>Instructor names used for evaluation assignments</strong><span class="muted">Add or activate the instructor names administrators can assign to courses.</span></summary><div class="section-head"><div><h2>Register an instructor for evaluation</h2><p class="muted">This keeps instructor records inside User Accounts instead of a separate page.</p></div><span class="count-pill"><?=count($profiles)?> records</span></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add_profile"><label>Instructor full name<input name="profile_name" required></label><label>College / school<input name="college"></label><label>Department<select name="profile_department" required><option value="">Select department</option><?php foreach($departments as $d):?><option value="<?=e($d['name'])?>"><?=e($d['name'])?></option><?php endforeach;?></select></label><label>Employee code<input name="employee_code"></label><div class="wide"><button class="btn primary">＋ Add instructor profile</button></div></form><div class="table-wrap"><table><thead><tr><th>Instructor</th><th>College / school</th><th>Department</th><th>Employee code</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($profiles as $p):?><tr><td><?=e($p['full_name'])?></td><td><?=e($p['college'])?></td><td><?=e($p['department'])?></td><td><?=e($p['employee_code'])?></td><td><?=$p['is_active']?'Active':'Inactive'?></td><td><form method="post" onsubmit="return confirm('Change this instructor profile status? Existing evaluation history will be preserved.')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle_profile"><input type="hidden" name="profile_id" value="<?=$p['id']?>"><button class="btn small secondary"><?=$p['is_active']?'Deactivate':'Reactivate'?></button></form></td></tr><?php endforeach;?></tbody></table></div></details>
<?php page_footer();?>
